  // ---- register block -------------------------------------------------------
  class companion_regs_reg_block extends uvm_reg_block;

    rand companion_regs_status_reg status;

    rand companion_regs_root_intr_enable_reg root_intr_enable;

    rand companion_regs_err_intr_enable_reg err_intr_enable;

    rand companion_regs_root_intr_mask_reg root_intr_mask;

    rand companion_regs_err_intr_mask_reg err_intr_mask;

    rand companion_regs_data_fifo_status_reg data_fifo_status;


    function new(string name = "companion_regs_reg_block");
      super.new(name, UVM_NO_COVERAGE);
    endfunction

    virtual function void build();
      // Byte-aligned LITTLE_ENDIAN map at base 0; bus width derives from
      // the regblock's CPUIF data width.
      this.default_map = create_map(
        .name      ("default_map"),
        .base_addr (8'h0),
        .n_bytes   (4),
        .endian    (UVM_LITTLE_ENDIAN),
        .byte_addressing (1'b1));


      this.status = companion_regs_status_reg::type_id::create("status");
      this.status.configure(this, null, "");
      this.status.build();
      this.default_map.add_reg(this.status, 8'h0, "RW");



      this.root_intr_enable = companion_regs_root_intr_enable_reg::type_id::create("root_intr_enable");
      this.root_intr_enable.configure(this, null, "");
      this.root_intr_enable.build();
      this.default_map.add_reg(this.root_intr_enable, 8'h40, "RW");



      this.err_intr_enable = companion_regs_err_intr_enable_reg::type_id::create("err_intr_enable");
      this.err_intr_enable.configure(this, null, "");
      this.err_intr_enable.build();
      this.default_map.add_reg(this.err_intr_enable, 8'h44, "RW");



      this.root_intr_mask = companion_regs_root_intr_mask_reg::type_id::create("root_intr_mask");
      this.root_intr_mask.configure(this, null, "");
      this.root_intr_mask.build();
      this.default_map.add_reg(this.root_intr_mask, 8'h60, "RW");



      this.err_intr_mask = companion_regs_err_intr_mask_reg::type_id::create("err_intr_mask");
      this.err_intr_mask.configure(this, null, "");
      this.err_intr_mask.build();
      this.default_map.add_reg(this.err_intr_mask, 8'h64, "RW");



      this.data_fifo_status = companion_regs_data_fifo_status_reg::type_id::create("data_fifo_status");
      this.data_fifo_status.configure(this, null, "");
      this.data_fifo_status.build();
      this.default_map.add_reg(this.data_fifo_status, 8'h20, "RO");



      lock_model();
    endfunction

  endclass : companion_regs_reg_block

endpackage : companion_regs_ral_pkg

