// =============================================================================
// UVM RAL smoke sequence for `companion_regs_ral_pkg`.
//
// A minimal `uvm_sequence` that exercises every register in the model
// with a read-after-write (RAW) pattern. Intended as a starting point for
// verification teams — not run by OSS CI (Verilator lacks UVM). Drop the
// sequence onto a sequencer connected to a `uvm_reg_predictor` and the
// generated `companion_regs_reg_block` to get smoke
// coverage of the RAL model itself.
// =============================================================================
`ifndef _COMPANION_REGS_RAL_SMOKE_SEQ_SV
`define _COMPANION_REGS_RAL_SMOKE_SEQ_SV

package companion_regs_ral_smoke_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import companion_regs_ral_pkg::*;

  class companion_regs_ral_smoke_seq extends uvm_sequence;
    `uvm_object_utils(companion_regs_ral_smoke_seq)

    companion_regs_reg_block model;
    uvm_status_e status;
    uvm_reg_data_t rdata;
    uvm_reg_data_t wdata;

    function new(string name = "companion_regs_ral_smoke_seq");
      super.new(name);
    endfunction

    virtual task body();
      if (model == null) begin
        `uvm_fatal(get_type_name(), "RAL model handle not assigned before smoke seq")
      end


      // status — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.status.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(status) status=%s", status.name()))
      end
      model.status.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(status) status=%s", status.name()))
      end



      // root_intr_enable — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.root_intr_enable.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(root_intr_enable) status=%s", status.name()))
      end
      model.root_intr_enable.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(root_intr_enable) status=%s", status.name()))
      end



      // err_intr_enable — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.err_intr_enable.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(err_intr_enable) status=%s", status.name()))
      end
      model.err_intr_enable.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(err_intr_enable) status=%s", status.name()))
      end



      // root_intr_mask — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.root_intr_mask.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(root_intr_mask) status=%s", status.name()))
      end
      model.root_intr_mask.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(root_intr_mask) status=%s", status.name()))
      end



      // err_intr_mask — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.err_intr_mask.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(err_intr_mask) status=%s", status.name()))
      end
      model.err_intr_mask.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(err_intr_mask) status=%s", status.name()))
      end



      // data_fifo_status — RO: read-only smoke (no write).
      model.data_fifo_status.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(data_fifo_status) status=%s", status.name()))
      end


    endtask

  endclass : companion_regs_ral_smoke_seq

endpackage : companion_regs_ral_smoke_pkg

`endif // _COMPANION_REGS_RAL_SMOKE_SEQ_SV

